/**
 * Bridge Schemas
 *
 * Zod schemas for bridge capability manifest, error response,
 * and sync state record.
 */

import { z } from "zod";

export const bridgeCapabilitySchema = z.enum([
  "read:workouts",
  "write:workouts",
  "read:body",
  // Body-composition/weight upload to the connector (garmin-bridge writes a
  // weight_scale FIT file). Announced by the bridge manifest; the export
  // data-flow wiring lands with the SPA integration.
  "write:body",
  "read:sleep",
  "read:training-plan",
  "read:training-zones",
  // Garmin executed-activity pull (F5). The domain `activity` type maps to
  // this token; the garmin-bridge announcers gain it in lockstep in V2.
  "read:activities",
]);

export const bridgeManifestSchema = z.object({
  id: z.string(),
  name: z.string(),
  version: z.string(),
  protocolVersion: z.number().int().positive(),
  capabilities: z.array(bridgeCapabilitySchema),
});

export type BridgeManifest = z.infer<typeof bridgeManifestSchema>;

export const bridgeErrorResponseSchema = z.object({
  ok: z.literal(false),
  error: z.string(),
  code: z.string().optional(),
  retryable: z.boolean().optional(),
});

export const syncStateSchema = z.object({
  source: z.string(),
  extensionId: z.string(),
  lastSeen: z.iso.datetime(),
  capabilities: z.array(bridgeCapabilitySchema),
  protocolVersion: z.number().int().positive(),
});

export type SyncState = z.infer<typeof syncStateSchema>;
